index bd6a26aa36cd..8b66a6724f86 100644
--- a/drivers/acpi/cppc_acpi.c
+++ b/drivers/acpi/cppc_acpi.c
@@ -2282,6 +2282,268 @@ int cppc_set_perf_limited(int cpu, u64 bits_to_clear)
 }
